REPLACE INTO `quest_template_locale` SET `ID`='1005674', `Locale`='zhCN', `Title`='真正的工匠：地狱布套装', `Details`='真正的工匠，是能创造出神话般奇迹的人。\\n\\n我们需要你的帮助。只有像你这样真正的工匠，才能把我们从这糟糕的处境里解救出来。\\n\\n收集 2 套地狱布套装，把它们带回任务板，换取一份像样的报酬，足够补偿你所有的辛劳。', `Objectives`='收集 1 件地狱布长袍。', `EndText`='', `CompletedText`='回到任务板。', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='';
