REPLACE INTO `quest_template_locale` SET `ID`='1007453', `Locale`='zhCN', `Title`='别有用心：制皮匠的手袋', `Details`='动物权利组织对我们获取毛皮的方式表示「关切」……$b$b我们需要你的帮助，英雄。也许这活不起眼——动物权利组织正因为我们要获取毛皮而纠缠不休——但这都不重要。重要的是，我需要你帮我收集一些毛皮回来！$b$b收集 1 个制皮匠的手袋。当然，你的援助必将得到丰厚的回报，英雄。', `Objectives`='收集 1 个制皮匠的手袋。', `EndText`='', `CompletedText`='回到任务板。', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='';
